action.command:
python3 -I -c "import json,pathlib
keys=('id','name','status','conclusion','created_at','run_started_at','updated_at','run_attempt','started_at','completed_at')
for p in sorted(pathlib.Path('.session/exports/actions').glob('*.json')):
 d=json.loads(p.read_text()); print('RUN',json.dumps({k:v for k,v in d.items() if k in keys}))
 for j in d['jobs']:
  print('JOB',json.dumps({k:v for k,v in j.items() if k in keys}))
  for s in j.get('steps',[]):
   if any(t in s.get('name','').lower() for t in ('runtime','result','epilogue','upload','download','session','pack')): print('STEP',json.dumps(s))"

